using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncDisposable
{
    private readonly FakeProvider provider = new();

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    private static readonly Money Amount = new(12.50m, "eur");

    [Fact]
    public async Task Sends_the_authorization_as_a_json_post_to_the_provider()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Gateway().AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        var seen = Assert.Single(provider.Requests);
        Assert.Equal("POST", seen.Method);
        Assert.Equal("/v1/authorizations", seen.Path);
        Assert.StartsWith("application/json", seen.ContentType);
        using var json = JsonDocument.Parse(seen.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Gateway().AuthorizeAsync("A", Amount, CancellationToken.None));
    }

    [Fact]
    public async Task A_declined_answer_is_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Gateway().AuthorizeAsync("A", Amount, CancellationToken.None));
    }

    [Fact]
    public async Task A_refusal_with_402_is_declined()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Gateway().AuthorizeAsync("A", Amount, CancellationToken.None));
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"decision":"approved"}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_explicit_approval_is_never_approved(string body)
    {
        provider.Respond(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Gateway().AuthorizeAsync("A", Amount, CancellationToken.None));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Provider_errors_surface_instead_of_looking_like_a_decision(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");

        await Assert.ThrowsAsync<HttpRequestException>(() => Gateway().AuthorizeAsync("A", Amount, CancellationToken.None));
    }

    [Fact]
    public async Task A_body_that_is_not_json_surfaces_as_an_error()
    {
        provider.Respond(200, "<html>oops</html>");

        await Assert.ThrowsAsync<JsonException>(() => Gateway().AuthorizeAsync("A", Amount, CancellationToken.None));
    }

    public async ValueTask DisposeAsync() => await provider.DisposeAsync();

    private sealed record SeenRequest(string Method, string Path, string? ContentType, string Body);

    // A real HTTP listener on loopback so the exact bytes on the wire are exercised.
    private sealed class FakeProvider : IAsyncDisposable
    {
        private readonly HttpListener listener = new();
        private readonly Task loop;
        private int status = 200;
        private string body = "";

        public FakeProvider()
        {
            var port = GetFreePort();
            BaseAddress = new Uri($"http://127.0.0.1:{port}");
            listener.Prefixes.Add($"http://127.0.0.1:{port}/");
            listener.Start();
            loop = Task.Run(Serve);
        }

        public Uri BaseAddress { get; }

        public List<SeenRequest> Requests { get; } = [];

        public void Respond(int statusCode, string responseBody) => (status, body) = (statusCode, responseBody);

        private async Task Serve()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception e) when (e is HttpListenerException or ObjectDisposedException) { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var requestBody = await reader.ReadToEndAsync();
                lock (Requests)
                {
                    Requests.Add(new(context.Request.HttpMethod, context.Request.Url!.AbsolutePath, context.Request.ContentType, requestBody));
                }

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        private static int GetFreePort()
        {
            var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
            probe.Start();
            var port = ((IPEndPoint)probe.LocalEndpoint).Port;
            probe.Stop();
            return port;
        }

        public async ValueTask DisposeAsync()
        {
            listener.Close();
            await loop;
        }
    }
}
